  ui_story_31530401_18_dialog_content = "Graças a eles, todos conseguem fazer mais 100 agachamentos!",
  ui_story_31530401_19_dialog_content = "Sério?! Não tenho mais energia...",
  ui_story_31530401_20_dialog_content = "Hmm? Soldados na última fila, marchem para frente!",
  ui_story_31530401_21_dialog_content = "Uh... Essa é a fila mais ao fundo?",
