  ui_story_31530401_55_dialog_content = "Mais um minuto de treinamento significa um pouco mais de força.",
  ui_story_31530401_56_dialog_content = "Estou sempre disposto a receber mais treinamento!",
  ui_story_31530401_57_option_content = "Você não precisa ser tão atencioso assim.",
  ui_story_31530401_58_dialog_content = "Não passei pelo treinamento, mas acabei de ficar na formação...",
  ui_story_31530401_59_dialog_content = "Foi minha culpa por falar livremente sem permissão.",
  ui_story_31530401_60_dialog_content = "Eu não me sentiria confortável em ter você recebendo a punição em meu lugar.",
  ui_story_31530401_61_dialog_content = "Vou fazer isso sozinho!",
  ui_story_31530401_62_dialog_content = "Hahaha, bem, já que a inexperiente Celestita diz isso...",
  ui_story_31530401_63_dialog_content = "Eu não posso simplesmente ficar parado esperando ser derrotado!",
  ui_story_31530401_64_dialog_content = "PlayerName, aceito o seu desafio de treinamento!",
  ui_story_31530401_65_dialog_content = "Como isso se tornou um desafio...?",
  ui_story_31530401_66_dialog_content = "Até o Grande Marechal está treinando tão duro... E-eu também vou participar!",
  ui_story_31530401_67_dialog_content = "Eu também quero melhorar minhas habilidades!",
  ui_story_31530401_68_dialog_content = "Instrutor! Todos nós queremos treinamento extra!",
  ui_story_31530401_69_dialog_content = "(Os novos recrutas que estavam reclamando agora estão animados, como se fossem pessoas completamente diferentes...)",
  ui_story_31530401_70_dialog_content = "(É este o poder da influência de Reinhardt?)",
  ui_story_31530401_71_dialog_content = "(Mas eu não esperava que a inspeção de Reinhardt fosse...)",
  ui_story_31530401_72_dialog_content = "(Tão cansativo!)",
  ui_story_31530401_73_dialog_content = "PlayerName, está quase amanhecendo. Hora de seguir para nossa próxima parada.",
  ui_story_31530401_74_dialog_content = "<color=#e8d9bb>Gannon City, Centro de Pesquisa</color>",
  ui_story_31530401_75_dialog_content = "Esses são os resultados de nossa pesquisa nos últimos dias. Naturalmente, continuaremos a iterar nossos projetos no futuro.",
  ui_story_31530401_76_dialog_content = "(Um modelo de videogame sem conteúdo algum, um campo colorido de rosas, um registro de observação de Hiiro...)",
  ui_story_31530401_77_dialog_content = "(Não sou especialista, mas... isso pode realmente ser chamado de resultados de pesquisa?)",
  ui_story_31530401_78_dialog_content = "A pesquisa científica requer mais paciência e resiliência do que o indivíduo médio possui.",
  ui_story_31530401_79_dialog_content = "Às vezes também requer um pouco de sorte, e tempo.",
  ui_story_31530401_80_dialog_content = "Sempre admirei nossos colegas no Centro de Pesquisa Illumina.",
  ui_story_31530401_81_dialog_content = "Estou honrado por ter tido a oportunidade de ver os resultados da sua pesquisa hoje. Isso me deixou uma grande impressão!",
  ui_story_31530401_82_dialog_content = "A máquina de videogame de Gronru ainda não tem nenhum conteúdo real...",
  ui_story_31530401_83_dialog_content = "Mas estou adivinhando que você está tentando criar um sistema de combate simulado para o povo de Illumina lutar contra os Eclipsitas.",
  ui_story_31530401_84_dialog_content = "Uma combinação brilhante de educação e entretenimento, além de melhorar as habilidades de combate de todos contra os Eclipsitas.",
  ui_story_31530401_85_dialog_content = "Estou impressionado com a sua visão de longo prazo!",
  ui_story_31530401_86_dialog_content = "Sério? Ha... Ha...",
  ui_story_31530401_87_dialog_content = "E essas variantes de rosas enganosamente belas que Jola está cultivando...",
  ui_story_31530401_88_dialog_content = "Seus espinhos são na verdade cem vezes mais afiados do que rosas comuns.",
  ui_story_31530401_89_dialog_content = "Se pudessem ser plantados na linha de frente, eles efetivamente reduziriam a velocidade dos Eclipsitas que se aproximam.",
  ui_story_31530401_90_dialog_content = "(Por que eu não pensei nisso?)",
  ui_story_31530401_91_dialog_content = "(Embora seria um destino cruel para estas belas flores...)",
  ui_story_31530401_92_dialog_content = "(Mas isso significa que finalmente tenho um plano de pesquisa viável para enviar!)",
  ui_story_31530401_93_dialog_content = "Sou apenas um soldado.",
  ui_story_31530401_94_dialog_content = "Estou profundamente comovido com a inovação e criatividade de sua pesquisa.",
  ui_story_31530401_95_dialog_content = "A pesquisa científica é como uma montanha que você escala, sempre se esforçando para alcançar seu pico, apesar de enfrentar inúmeros obstáculos.",
  ui_story_31530401_96_dialog_content = "Ao longo do tempo, os pesquisadores têm sido o coração da Federação Illumina. Sem qualquer um de vocês...",
  ui_story_31530401_97_dialog_content = "Não haveria uma única refeição para o povo de Illumina, nem uma única arma nas mãos dos soldados Illumina.",
  ui_story_31530401_98_dialog_content = "Não hesite ao solicitar o financiamento da pesquisa para o próximo ano! Eu o apoiarei totalmente!",
  ui_story_31530401_99_dialog_content = "Grande Marechal, vou cultivar imediatamente um novo tipo de rosa de combate!",
  ui_story_31530401_100_dialog_content = "Se a ideia do jogo de combate Eclipsite puder ser realizada, significa que podemos competir com mais pessoas em tempo real, certo?",
  ui_story_31530401_101_dialog_content = "As coisas estão ficando realmente interessantes. Eu vou acelerar...",
  ui_story_31530401_102_dialog_content = "Também vamos aprofundar nossos registros de pesquisa sobre o Comandante Hiiro!",
  ui_story_31530401_103_dialog_content = "Huh? Ah... M-Eu também... Eu também... vou realizar alguns experimentos...",
  ui_story_31530401_104_dialog_content = "(Todos pareciam deprimidos com os resultados de suas pesquisas, mas agora há um renovado espírito de luta em seus olhos...)",
  ui_story_31530401_105_dialog_content = "(É essa... a magia de Reinhardt?)",
  ui_story_31530401_106_dialog_content = "Devemos também nos despedir?",
  ui_story_31530401_107_dialog_content = "Hã?",
  ui_story_31530401_108_dialog_content = "Para o próximo lugar!",
  ui_story_31530401_109_dialog_content = "<color=#e8d9bb>Illumina: A Linha de Frente</color>",
  ui_story_31530401_110_dialog_content = "Hiiro, vou liderar uma equipe para a frente para cavar trincheiras.",
  ui_story_31530401_111_dialog_content = "As outras equipes seguirão seu plano original!",
  ui_story_31530401_112_dialog_content = "Sim, Grande Marechal!",
  ui_story_31530401_113_dialog_content = "PlayerName, pegue uma pá e me siga.",
  ui_story_31530401_114_dialog_content = "Uhh? Vamos para a linha de frente para cavar trincheiras?",
  ui_story_31530401_115_dialog_content = "Isso tudo realmente acontece em um dia...?",
  ui_story_31530401_116_dialog_content = "Companheiros Illuminans! A guerra é cruel, e o medo diante da batalha é apenas nossa reação instintiva.",
  ui_story_31530401_117_dialog_content = "A batalha que acabou de terminar foi uma grande vitória para nós.",
  ui_story_31530401_118_dialog_content = "Todos conquistaram seus medos e perseveraram até o fim.",
  ui_story_31530401_119_dialog_content = "Cada um de vocês é um herói. Vocês são o orgulho da Illumina!",
  ui_story_31530401_120_dialog_content = "No entanto, a vitória final ainda não está conosco.",
  ui_story_31530401_122_dialog_content = "Novas trincheiras estão esperando para serem cavadas por nós! Novas frentes de batalha estão esperando para serem definidas por nós!",
  ui_story_31530401_123_dialog_content = "Agora, vamos continuar a nos dedicar às batalhas que virão!",
  ui_story_31530401_124_dialog_content = "Grande marechal! Grande marechal! Grande marechal!",
  ui_story_31530401_125_dialog_content = "(Os soldados que foram desmoralizados pelo ataque anterior têm olhos brilhantes novamente.)",
  ui_story_31530401_126_dialog_content = "(Reinhardt...)",
  ui_story_31530401_127_dialog_content = "Vamos!",
  ui_story_31530401_128_dialog_content = "Em frente!",
  ui_story_31530401_129_dialog_content = "Em frente!",
  ui_story_31530401_130_dialog_content = "<color=#e8d9bb>Gannon City, Distrito Administrativo</color>",
  ui_story_31530401_131_dialog_content = "C-Cobrar...",
  ui_story_31530401_132_dialog_content = "Hahaha, não estamos mais na linha de frente. Para onde você planeja avançar?",
  ui_story_31530401_133_dialog_content = "Ah, c-certo.",
  ui_story_31530401_134_dialog_content = "... Desculpe, provavelmente ainda não recuperei meus sentidos.",
  ui_story_31530401_135_dialog_content = "Sente-se aqui e descanse um pouco. Você pode resumir todas as anotações de hoje enquanto descansa.",
  ui_story_31530401_136_dialog_content = "Vou à sala de conferências para uma reunião. Deve ser rápida.",
  ui_story_31530401_137_dialog_content = "T-tudo bem!",
  ui_story_31530401_138_dialog_content = "(Reinhardt cavou trincheiras com os soldados por horas antes...)",
  ui_story_31530401_139_dialog_content = "(E eles até cavaram o dobro do comprimento esperado!)",
  ui_story_31530401_140_dialog_content = "(Ugh... Eu não consigo mais fazer isso. É demais para o meu corpo...!)",
  ui_story_31530401_141_dialog_content = "*Roncar*",
  ui_story_31530401_142_dialog_content = "PlayerName?",
  ui_story_31530401_143_dialog_content = "Pare de se distrair e venha para a reunião.",
  ui_story_31530401_144_dialog_content = "Reunião? Eu também tenho que ir? Q-Quem mais vai participar?",
  ui_story_31530401_145_dialog_content = "Hahaha, você saberá quando entrar.",
  ui_story_31530401_146_dialog_content = "Ai...",
  ui_story_31530401_147_dialog_content = "PlayerName, você nem mesmo completou sua corrida de 60 milhas. Por que já está indo embora?",
  ui_story_31530401_148_dialog_content = "Tsk, PlayerName, por que não vem treinar comigo? Meu treinamento não é menos intenso que o de Sharona!",
  ui_story_31530401_149_dialog_content = "Uh oh, a linha de frente foi violada pelos Eclipsitas... PlayerName, solicitando apoio!",
  ui_story_31530401_150_dialog_content = "Não vá, PlayerName.",
  ui_story_31530401_151_dialog_content = "Tente meu super jogo estratégico de conexão para derrotar os Eclipsitas primeiro!",
  ui_story_31530401_152_dialog_content = "Um de cada vez, todos...",
  ui_story_31530401_153_dialog_content = "Um de cada vez...",
  ui_story_31530401_154_dialog_content = "<color=#828282>Bam!</color>",
  ui_story_31530401_155_dialog_content = "*Roncar*",
  ui_story_31530401_156_dialog_content = "(Isso foi assustador. Foi apenas um sonho...)",
  ui_story_31530401_157_dialog_content = "Você finalmente acordou.",
  ui_story_31530401_158_dialog_content = "(Hã? A reunião do Reinhardt já acabou?)",
  ui_story_31530401_159_dialog_content = "(Mas ela... Por que ela parece tão brava?)",
  ui_story_31530401_160_dialog_content = "(Oh não... Ela me pediu para fazer um resumo das minhas anotações, mas eu adormeci sem escrever uma palavra...)",
  ui_story_31530401_161_dialog_content = "(Reinhardt deve estar bravo por causa disso...)",
  ui_story_31530401_162_dialog_content = "(O que eu faço agora? Alguém me ajude, por favor...)",
  ui_story_31530401_163_dialog_content = "<color=#e8d9bb>*ronco do estômago*</color>",
  ui_story_31530401_164_dialog_content = "Hã? Foi isso...",
  ui_story_31530401_165_dialog_content = "Ahem. Desculpe, parece que meu estômago está protestando.",
  ui_story_31530401_166_dialog_content = "Ainda temos tempo. Vamos para a cantina!",
  ui_story_31530401_167_dialog_content = "Tá bom...",
  ui_story_31530401_168_dialog_content = "(Por que ela está tão quieta? Ela deve ainda estar brava.)",
  ui_story_31530401_169_dialog_content = "(A atmosfera está tão estranha...)",
  ui_story_31530401_170_dialog_content = "Um... sinto muito!",
  ui_story_31530401_171_dialog_content = "Hã? Por que você está pedindo desculpas?",
  ui_story_31530401_172_dialog_content = "Eu estava muito cansado mais cedo... então eu não terminei de escrever o resumo de hoje...",
  ui_story_31530401_173_dialog_content = "Por favor, não fique bravo... Eu vou encontrar tempo para completar!",
  ui_story_31530401_174_dialog_content = "Eu? Bravo?",
  ui_story_31530401_175_dialog_content = "Hahahaha, desculpe, desculpe! Não consigo evitar franzir a testa quando estou com fome.",
  ui_story_31530401_176_dialog_content = "Vivian tem me repreendido sobre isso há muito tempo, mas eu não larguei o hábito.",
  ui_story_31530401_177_dialog_content = "Oh! Entendi.",
  ui_story_31530401_178_option_content = "Isso é um alívio.",
  ui_story_31530401_179_dialog_content = "Hmm? Você está feliz que eu não me livrei desse meu mau hábito?",
  ui_story_31530401_180_dialog_content = "Isso é... Desculpe, não! Não foi isso que eu quis dizer!",
  ui_story_31530401_181_dialog_content = "Mas eu não acho que é realmente um hábito ruim.",
  ui_story_31530401_182_option_content = "Que hábito interessante.",
  ui_story_31530401_183_dialog_content = "Parece que o sempre perfeito Grande Marechal parece um pouco mais próximo de nós, pessoas normais, agora.",
  ui_story_31530401_184_dialog_content = "Sempre perfeito? Eu não diria isso sobre mim mesmo.",
  ui_story_31530401_185_dialog_content = "Como você não está? Você fez tanto em um dia hoje quanto eu faço em um mês!",
  ui_story_31530401_186_dialog_content = "E cada tarefa única foi tratada perfeitamente, sem falhas.",
  ui_story_31530401_187_dialog_content = "Não é à toa que o povo de Illumina idolatra tanto o Grande Marechal.",
  ui_story_31530401_188_dialog_content = "Vi isso com meus próprios olhos hoje. Você deve conhecer algum tipo de magia para manipular a mente das pessoas!",
  ui_story_31530401_189_dialog_content = "Hahahaha, PlayerName, você tem muita imaginação!",
  ui_story_31530401_190_dialog_content = "O trabalho de um novo recruta é treinar, o trabalho de um pesquisador é experimentar...",
  ui_story_31530401_191_dialog_content = "E o trabalho do Grande Marechal é traçar a estratégia a seguir quando as pessoas perdem o seu caminho.",
  ui_story_31530401_192_dialog_content = "Se você insistir em dizer que eu tenho algum tipo de habilidade mágica, eu só posso dizer—",
  ui_story_31530401_193_dialog_content = "Isso faz de nós dois!",
  ui_story_31530401_194_dialog_content = "Hã?",
  ui_story_31530401_195_dialog_content = "O lendário último Celestita carece de força física e é, por falta de uma palavra melhor, frágil.",
  ui_story_31530401_196_dialog_content = "Ainda assim, você consegue fazer com que tantas pessoas se juntem a você em suas aventuras.",
  ui_story_31530401_197_dialog_content = "Até o subordinado de Vivian, Vice, está disposto a seguir você em suas andanças pelo mundo.",
  ui_story_31530401_198_dialog_content = "Você também usa magia para atrair pessoas para você?",
  ui_story_31530401_199_dialog_content = "Isso...",
  ui_story_31530401_200_dialog_content = "<color=#e8d9bb>*ronco do estômago*</color>",
  ui_story_31530401_201_dialog_content = "Hahaha! Parece que o seu estômago também começou a protestar, hein?",
  ui_story_31530401_202_dialog_content = "Vamos, vamos satisfazê-los primeiro.",
  ui_story_31530401_203_dialog_content = "Então voltaremos e terminaremos o resto da papelada, e continuaremos essa conversa depois!",
  ui_story_31530401_204_dialog_content = "(Vamos continuar trabalhando?!)",
  ui_story_31530401_205_dialog_content = "(Quando este dia vai acabar...)",
  ui_story_31530401_206_dialog_content = "(Reinhardt não é uma Grande Marechal, tenho certeza que ela é algum tipo de criatura inesgotável.)",
  ui_story_31530401_207_dialog_content = "Uhul!",
  ui_story_31530401_208_dialog_content = "Delícia! Assado de panela é o melhor!",
  ui_story_31530401_209_dialog_content = "Outra porção, por favor!",
  ui_story_31530601_1_dialog_content = "Esse homem jovem é o lendário Celestita?",
  ui_story_31530601_2_dialog_content = "De jeito nenhum, ele parece muito maltrapilho para ser algum tipo de lenda.",
  ui_story_31530601_3_dialog_content = "Todos têm seus próprios gostos. Talvez ele apenas prefira parecer assim?",
  ui_story_31530601_4_dialog_content = "Mas como o único sobrevivente de uma raça inteira, ele deve ter herdado algum tipo de fortuna, certo? Ele até possui todo o Eraveil—",
  ui_story_31530601_5_dialog_content = "(Eles estiveram me encarando todo esse tempo... E agora estão começando a dizer algumas coisas realmente absurdas.)",
  ui_story_31530601_6_dialog_content = "(Este é realmente o lugar certo? Por que ela me convidaria para um banquete tão chique...?)",
  ui_story_31530601_7_dialog_content = "\"Caro PlayerName,\"",
  ui_story_31530601_8_dialog_content = "\"Se você tiver tempo, poderia vir até Umbraton? O endereço é #XXX na rua XXXX. P.S. Mesmo que você não tenha tempo, por favor, faça o possível para aparecer.\"",
  ui_story_31530601_9_dialog_content = "Perdoe-me, mas você é o representante de Eraveil?",
  ui_story_31530601_10_dialog_content = "Hã?!",
  ui_story_31530601_11_dialog_content = "Eu te conheço. Você é o último celestita, herdando o poder mais maligno da sua raça.",
  ui_story_31530601_12_dialog_content = "Você controla as mentes de qualquer criatura viva em Astra! Com um único capricho, você pode transformar todos nesta sala em seu fantoche!",
  ui_story_31530601_13_dialog_content = "Agora apenas espere um segundo!",
  ui_story_31530601_14_dialog_content = "Transformar-nos em marionetes, você diz? Desculpe, mas a riqueza e o status já são mais do que capazes de realizar isso. Não dê ouvidos a essas pessoas, meu amigo; você verá que alguns nobres são superiores aos demais.",
  ui_story_31530601_15_dialog_content = "Ninguém quer fazer amizade com a sujeira, mas eu posso ajudá-lo nesse aspecto.",
  ui_story_31530601_16_dialog_content = "E-Eu posso cuidar de mim mesmo, obrigado...",
  ui_story_31530601_17_dialog_content = "O que? O Celestita? Onde?! Deixe-me ver, deixe-me ver—",
  ui_story_31530601_18_dialog_content = "—Senhoras e senhores.",
  ui_story_31530601_19_dialog_content = "(Aquela voz...!)",
  ui_story_31530601_20_dialog_content = "Aproximar-se dele é perfeitamente aceitável, mas peço que se comportem com um pouco mais de dignidade.",
  ui_story_31530601_21_dialog_content = "Se por nenhum outro motivo, então faça pelo menos por mim. Afinal—",
  ui_story_31530601_22_dialog_content = "PlayerName está aqui a meu pedido.",
  ui_story_31530601_23_dialog_content = "Reinhardt...! Você realmente está aqui!",
  ui_story_31530601_24_dialog_content = "(E em uma roupa tão formal também...)",
  ui_story_31530601_25_dialog_content = "O Grande Marechal de Illumina! Ela convidou o Celestita...",
  ui_story_31530601_26_dialog_content = "E o Celestita a chamou pelo nome...",
  ui_story_31530601_27_dialog_content = "Sr. PlayerName, você deve vir ao próximo baile da nossa família!",
  ui_story_31530601_28_dialog_content = "Seria uma honra ter você como nosso convidado!",
  ui_story_31530601_29_dialog_content = "Por aqui, PlayerName.",
  ui_story_31530601_30_dialog_content = "(... estou salvo!)",
  ui_story_31530601_31_dialog_content = "<color=#e8d9bb>A multidão instintivamente se separou, e todos os olhos estavam fixos em cada passo deles enquanto subiam as escadas.</color>",
  ui_story_31530601_32_dialog_content = "... Desculpe por isso. Eu estava no meio de uma reunião importante e não consegui me afastar a tempo de te salvar daquelas pessoas.",
  ui_story_31530601_33_dialog_content = "Não se preocupe com isso! Se não fosse por isso, eu nunca teria sabido o quão ridículos os rumores sobre mim se tornaram.",
  ui_story_31530601_34_dialog_content = "Aparentemente, eu sou um vilão rico capaz de escravizar todas as mentes em Astra... Depois de hoje, não ficaria surpreso se começassem a acusar a Illumina de estar em conluio com Eraveil!",
  ui_story_31530601_35_dialog_content = "Hahaha, então parece que eu estava preocupado à toa! Bom, eu gosto de ver esse lado <color=#FFB400>livre e indisciplinado</color> seu.",
  ui_story_31530601_36_dialog_content = "Não tenho certeza se isso foi um elogio ou não...",
  ui_story_31530601_37_dialog_content = "Você está muito diferente do normal hoje. Estou tendo dificuldades para te entender agora.",
  ui_story_31530601_38_dialog_content = "Diferente? Está dizendo que estou mais legal que o normal?",
  ui_story_31530601_39_dialog_content = "Eu estava prestes a dizer isso! Mas... sim, sua frieza e sua presença parecem muito diferentes, meio que—",
  ui_story_31530601_40_dialog_content = "Você está prestes a dizer algo duro, \"Nada mal, agora comece a fazer essas armas!\" ou \"Quero o perfil dele na minha mesa em dez minutos.\"",
  ui_story_31530601_41_dialog_content = "... Eu não acho que o Grande Marechal de Illumina deveria parecer assim para ninguém!",
  ui_story_31530601_42_dialog_content = "Mas foi assim que eu me senti quando você me resgatou do público... Foi tão legal!",
  ui_story_31530601_43_dialog_content = "Essas pessoas não são nada como você. Tudo o que eles se importam são os próprios interesses... Mas tudo bem, já que o mundo ainda precisa de pessoas como elas.",
  ui_story_31530601_44_dialog_content = "Eu vou cuidar deles, então por favor viva livremente e a seu bel-prazer.",
  ui_story_31530601_45_dialog_content = "Isso é algo que só você pode fazer.",
  ui_story_31530601_46_dialog_content = "Só eu...?",
  ui_story_31530601_47_dialog_content = "Fiquei surpreso ao saber que Reinhardt havia convidado um convidado esta noite - mas considerando que é PlayerName, eu entendo completamente.",
  ui_story_31530601_48_dialog_content = "Senhor das Sombras...!",
  ui_story_31530601_49_dialog_content = "(Então, a reunião importante era entre ele e Reinhardt?)",
  ui_story_31530601_50_dialog_content = "Ser o Shadowlord deve ser cansativo às vezes. Os soldados de Illumina são geralmente retos e simples, o que torna o trato com eles bastante direto. Você, por outro lado, tem que lidar com aquelas pessoas lá embaixo.",
  ui_story_31530601_51_dialog_content = "Na minha opinião, inspirar e liderar as massas retas e simples é um trabalho muito mais assustador.",
  ui_story_31530601_52_dialog_content = "As negociações de hoje teriam sido impossíveis sem a sua presença.",
  ui_story_31530601_53_dialog_content = "Só posso fazer um terço do trabalho, então vou dar o meu melhor.",
  ui_story_31530601_54_dialog_content = "O resto fica a seu critério e da Senhora Carleen.",
  ui_story_31530601_55_dialog_content = "(Carleen também estava lá?! Onde será que ela está agora...?)",
  ui_story_31530601_56_dialog_content = "Grande Marechal Reinhardt! E PlayerName, meu querido amigo!",
  ui_story_31530601_57_dialog_content = "(Quando nos tornamos amigos?!)",
  ui_story_31530601_58_dialog_content = "Gostaria de se juntar a mim e aos meus amigos para uma breve conversa? Eles são nobres de Lumópolis, vê, e—",
  ui_story_31530601_59_dialog_content = "O que você estava dizendo agora há pouco, PlayerName? Que Eclipsitas se infiltraram na Colossus? Não se preocupe, eu vou te ajudar a acabar com eles!",
  ui_story_31530601_60_dialog_content = "Hã?! Ah... Is-Isso mesmo! Toneladas de Eclipsitas! Vice tem defendido eles por três dias agora! Nós realmente poderíamos usar sua ajuda!",
  ui_story_31530601_61_dialog_content = "Como você pode ver, meu bom homem, nosso amigo está em grande necessidade de assistência. Se nos der licença, precisamos ir.",
  ui_story_31530601_62_dialog_content = "Por favor, tenha cuidado. Certamente vou notificar a Senhora Carleen sobre a sua situação.",
  ui_story_31530601_63_dialog_content = "Ah, de volta à Cidade Gannon!",
  ui_story_31530601_64_dialog_content = "Eu costumava achar este lugar tão apertado e sufocante, mas depois daquele banquete, cada respiração de ar pareceu tão refrescante!",
  ui_story_31530601_65_dialog_content = "...",
  ui_story_31530601_66_dialog_content = "(... Opa! Eu não deveria ter dito isso em voz alta!)",
  ui_story_31530601_67_dialog_content = "Não se preocupe, não vou ficar chateado com o que você disse sobre a Cidade Gannon.",
  ui_story_31530601_68_dialog_content = "Ela viu através de mim!",
  ui_story_31530601_69_dialog_content = "Além disso, para alguém tão livre quanto você, este lugar definitivamente pareceria apertado e abafado.",
  ui_story_31530601_70_dialog_content = "Ninguém... deveria jamais se acostumar a viver assim.",
  ui_story_31530601_71_dialog_content = "... Posso perguntar por que você me convidou para aquele banquete em Umbraton hoje? Ou por que você me pediu para te levar de volta para Gannon City antes que acabasse?",
  ui_story_31530601_72_dialog_content = "V-Você não estava planejando me usar como desculpa para sair, certo?",
  ui_story_31530601_73_dialog_content = "Você é meu querido amigo e um aliado confiável. Por que eu faria piada de você assim?",
  ui_story_31530601_74_dialog_content = "O motivo pelo qual eu pedi para você vir é... Cuidado!",
  ui_story_31530601_75_dialog_content = "(Isso foi por pouco... Quase fui atropelado por aquele veículo de transporte! Devo prestar mais atenção ao meu redor...)",
  ui_story_31530601_76_dialog_content = "Cuidado por onde anda. O setor mais novo de Gannon não precisa de nenhum sacrifício vivo.",
  ui_story_31530601_77_dialog_content = "E-Eu sinto muito! Espere, setor mais novo? Vocês estão desenvolvendo uma nova área?",
  ui_story_31530601_78_dialog_content = "Agora que você mencionou... aquele veículo de transporte estava carregando um monte de plantas, não estava? Eu não acho que já vi uma única planta na cidade de Gannon antes.",
  ui_story_31530601_79_dialog_content = "Hehehe.",
  ui_story_31530601_80_dialog_content = "... Estou realmente imaginando coisas?! Aquela risada quase soou como se você estivesse satisfeito consigo mesmo!",
  ui_story_31530601_81_dialog_content = "Você saberá quando ver por si mesmo. Venha comigo!",
  ui_story_31530601_82_dialog_content = "E-Esta ainda é... a cidade de Gannon?",
  ui_story_31530601_83_dialog_content = "Não acredito...",
  ui_story_31530601_84_dialog_content = "Posso garantir que esta ainda é a cidade de Gannon. Bem-vindo ao nosso mais novo setor residencial.",
  ui_story_31530601_85_dialog_content = "Quando projetamos este lugar, queríamos que fosse algo que até mesmo um Celestita livre e indisciplinado admiraria.",
  ui_story_31530601_86_dialog_content = "Eu? Mas por quê? Não para dar desculpas para minhas falhas ou algo assim, mas existem muitas outras pessoas livres e indisciplinadas no mundo.",
  ui_story_31530601_87_dialog_content = "Eu não vejo isso como uma falha em tudo.",
  ui_story_31530601_88_dialog_content = "Você está acostumado a viver no mundo aberto e desfruta de um senso de independência que permite ver tudo o que ele tem a oferecer—",
  ui_story_31530601_89_dialog_content = "É isso que significa ser livre e indisciplinado. Não é uma falha; é uma forma rara de felicidade que poucas pessoas vão experimentar.",
  ui_story_31530601_90_dialog_content = "E essa felicidade é algo que eu quero proporcionar para cada pessoa em Illumina.",
  ui_story_31530601_91_dialog_content = "!!!",
  ui_story_31530601_92_dialog_content = "Por séculos, o povo de Illumina viveu vidas frugais no subsolo, tudo em preparação para uma guerra sem fim.",
  ui_story_31530601_93_dialog_content = "Não temos escolha a não ser viver assim, mas isso não significa que não merecemos algo melhor.",
  ui_story_31530601_94_dialog_content = "É por isso que propus um novo plano para melhorar a vida de nossos cidadãos. Este setor mais recente é o local de teste para este plano.",
  ui_story_31530601_95_dialog_content = "PlayerName, você me ajudaria?",
  ui_story_31530601_96_dialog_content = "Como aliado da Illumina e a pessoa mais livre do mundo—",
  ui_story_31530601_97_dialog_content = "Por favor, dê-me uma avaliação honesta do nosso setor mais recente. Sua percepção é algo que valorizo muito.",
  ui_story_31530601_98_dialog_content = "Reinhardt... Estou impressionado que você tenha inventado algo tão incrível!",
  ui_story_31530601_99_dialog_content = "Claro que vou te ajudar! M-Mas não tenho certeza exata de como avaliar este lugar...",
  ui_story_31530601_100_dialog_content = "É simples. Apenas me dê sua opinião mais sincera sobre isso.",
  ui_story_31530601_101_dialog_content = "Espere! Do outro lado da rua... É um fornecedor de automóveis?",
  ui_story_31530601_102_dialog_content = "Ouvi dizer que você e seus amigos descobriram algo assim em uma antiga Cidade Baixa. Isso despertou minha curiosidade, então eu pedi para Gronru montar um modelo de teste.",
  ui_story_31530601_103_dialog_content = "Bem? É algo como o original?",
  ui_story_31530601_104_dialog_content = "Vamos descobrir. Um bar de café da manhã, por favor...",
  ui_story_31530601_105_dialog_content = "Realmente saiu!",
  ui_story_31530601_106_dialog_content = "Isso é incrível! A comida sempre foi racionada aqui na Cidade Gannon, mas agora pode ser servida sob demanda...",
  ui_story_31530601_107_dialog_content = "É apenas uma questão de curso. Agora que nossos recursos são suficientes para nos sustentar, acessibilidade e conveniência se tornam nossas próximas prioridades. Além disso, ninguém gosta de fazer fila para as coisas.",
  ui_story_31530601_108_dialog_content = "Vamos para a próxima rua.",
  ui_story_31530601_109_dialog_content = "Que parque lindo! Nunca vi algo tão verde em Gannon City antes...",
  ui_story_31530601_110_dialog_content = "Migard afirma que todas essas plantas são capazes de crescer bem sob iluminação artificial.",
  ui_story_31530601_111_dialog_content = "Eu também mantenho dois no meu quarto. Se alguém como eu pode mantê-los vivos, então o resto da Cidade Gannon não deveria ter um problema em fazer o mesmo!",
  ui_story_31530601_112_dialog_content = "E todas essas plataformas de salto e equipamentos de treinamento... São para exercícios?",
  ui_story_31530601_113_dialog_content = "Bom olho. Na verdade, tenho orgulho de chamar isso de alguns dos meus melhores trabalhos.",
  ui_story_31530601_114_dialog_content = "Até alguém que evita exercícios pode ser tentado a experimentar esses. Você não acha?",
  ui_story_31530601_115_dialog_content = "Vamos, você deveria experimentar. Eu vou te ajudar!",
  ui_story_31530601_116_dialog_content = "E-Eu estou bem, mas... Eu posso dizer que este lugar mudou. Eu poderia até descrevê-lo como \"vibrante\" agora...",
  ui_story_31530601_117_dialog_content = "... Espere, eu entendi agora! Você foi àquele banquete em Umbraton por causa desse novo setor, não foi?",
  ui_story_31530601_118_dialog_content = "Correto! Illumina se tornou excessivamente militarizada, tanto que certas necessidades diárias se tornaram escassas.",
  ui_story_31530601_119_dialog_content = "Se realmente desejamos expandir, precisaremos do apoio de ambos, Umbraton e Lumopolis.",
  ui_story_31530601_120_dialog_content = "Você não quer que barras de comida sejam a única coisa em nossos vendedores automáticos, certo?",
  ui_story_31530601_121_dialog_content = "Então é por isso que você estava se encontrando com Carleen e Istvan...",
  ui_story_31530601_122_dialog_content = "Uma proposta de negócio que beneficiaria todas as três partes - esse foi o acordo que alcançamos naquela época.",
  ui_story_31530601_123_dialog_content = "Mas naturalmente, um acordo entre três líderes não será suficiente. Nobres, guildas, gangues... O mais importante é ter todos eles a bordo, também.",
  ui_story_31530601_124_dialog_content = "É por isso que todas aquelas pessoas ricas e importantes estavam lá também?",
  ui_story_31530601_125_dialog_content = "Claro. Afinal, qual deles poderia se dar ao luxo de perder uma oportunidade de negócio como essa? Para ser honesto, não sou muito bom em lidar com eles, assim como você.",
  ui_story_31530601_126_dialog_content = "Mas eu definitivamente vou pegar o jeito algum dia. Até os comerciantes mais astutos não são nada comparados aos teimosos idosos com quem tenho que trabalhar todos os dias.",
  ui_story_31530601_127_dialog_content = "Determinada, capaz e tática... Essa é a Grande Marechal da Illumina.",
  ui_story_31530601_128_dialog_content = "Mas isso é muito para lidar sozinho... Você não vai se sentir exausto?",
  ui_story_31530601_129_dialog_content = "Dificilmente acho isso. Afinal, não sou eu quem dirige veículos de transporte ou cuida das plantas.",
  ui_story_31530601_130_dialog_content = "Isso não significa que seu prato não esteja cheio. Você mencionou Gronru e Migard, bem como este lugar ter \"alguns de seus melhores trabalhos\"...",
  ui_story_31530601_131_dialog_content = "Não adianta negar. Você tem suas mãos em quase todos os aspectos do desenvolvimento do novo setor!",
  ui_story_31530601_132_dialog_content = "A-Aham... É importante monitorar cada passo de um processo como este... Além disso, não estou procurando elogios pessoais aqui.",
  ui_story_31530601_133_dialog_content = "Estou pedindo sua opinião sincera sobre este lugar.",
  ui_story_31530601_134_dialog_content = "Não me veja como o Grande Marechal, mas como outro amigo e camarada de armas, e me diga exatamente o que você pensa sobre isso. Até mesmo críticas duras são totalmente aceitáveis!",
  ui_story_31530601_135_option_content = "Eu realmente acho o novo setor incrível.",
  ui_story_31530601_136_dialog_content = "É tão calmo e tranquilo. Até mesmo alguém tão sério quanto você se sente relaxado o suficiente para conversar tanto comigo aqui. Não é esse o ponto?",
  ui_story_31530601_137_dialog_content = "Você acha... Eu me sinto relaxado?",
  ui_story_31530601_138_option_content = "Acho que você está esperando demais de si mesmo.",
  ui_story_31530601_139_dialog_content = "Depois de ouvir você falar sobre o novo setor, posso dizer que você deu muito a este lugar. Você parece tão feliz e orgulhoso, como se estivesse apresentando algo que ama muito.",
  ui_story_31530601_140_dialog_content = "Eu pareço... feliz?",
  ui_story_31530601_141_dialog_content = "Você quer dizer que não percebeu?",
  ui_story_31530601_142_dialog_content = "Você mencionou tantas coisas sobre você mesmo agora. Como você odeia esperar na fila, ou como você não consegue cuidar de plantas... E como se sente orgulhoso quando as coisas são feitas.",
  ui_story_31530601_143_dialog_content = "Hahahahahahahahaha!",
  ui_story_31530601_144_dialog_content = "Eu sabia que convidá-lo aqui era a escolha certa!",
  ui_story_31530601_145_dialog_content = "Ah... Não consigo me lembrar da última vez que ri tanto.",
  ui_story_31530601_146_dialog_content = "Acho que foi quando eles ainda estavam por perto...",
  ui_story_31530601_147_dialog_content = "Eles? Você quer dizer...",
  ui_story_31530601_148_dialog_content = "Minha irmã, bem como Helios.",
  ui_story_31530601_149_dialog_content = "Costumávamos fazer tudo juntos. Estudar, treinar e viver nossas vidas.",
  ui_story_31530601_150_dialog_content = "No nosso tempo livre, também vínhamos a lugares como este e olhávamos para a Cidade Gannon de cima. Falávamos sobre todo tipo de coisa sem sentido, rindo enquanto apreciávamos a brisa.",
  ui_story_31530601_151_dialog_content = "Pensar naquele tempo me faz sentir tanta nostalgia.",
  ui_story_31530601_152_dialog_content = "Reinhardt...",
  ui_story_31530601_153_dialog_content = "Mas não se preocupe. Nada pode permanecer o mesmo, e enquanto algumas mudanças realmente podem nos sobrecarregar—",
  ui_story_31530601_154_dialog_content = "Na maioria das vezes, a mudança é emocionante.",
  ui_story_31530601_155_dialog_content = "Basta olhar para a Cidade de Gannon: está mudando de um lugar apertado e sufocante para uma cidade vibrante e aberta, não está?",
  ui_story_31530601_156_dialog_content = "E de acordo com a sua imaginação, até eu pareço mais relaxado e falante agora.",
  ui_story_31530601_157_dialog_content = "Eu não estava imaginando nada!",
  ui_story_31530601_158_dialog_content = "Heheh. Você também é uma pessoa bastante incrível.",
  ui_story_31530601_159_dialog_content = "Depois de todos esses anos, você me ajudou a lembrar como é conversar e rir com meus amigos... E isso é mais do que suficiente para mim.",
  ui_story_31530601_160_dialog_content = "... Reinhardt?",
  ui_story_31530601_161_dialog_content = "Mas Denier e Helios não estão mais comigo... E depois de hoje, você voltará a voar por todo o mundo novamente.",
  ui_story_31530601_162_dialog_content = "E eu estarei aqui, vigiando toda a cidade de Gannon.",
  ui_story_31530601_163_dialog_content = "Vou testemunhar o surgimento deste novo setor, um espaço verde e vibrante para todos desfrutarem.",
  ui_story_31530601_164_dialog_content = "É um lugar onde nosso povo pode viver sem restrições e escolher as coisas que querem comer.",
  ui_story_31530601_165_dialog_content = "Para os cidadãos de Illumina, o treinamento não é apenas nosso dever; também é um hobby e uma maneira de manter a saúde.",
  ui_story_31530601_166_dialog_content = "Aqui, as crianças podem subir aos lugares mais altos e passar um tempo precioso com seus amigos, rindo e olhando para a cidade como nós já fizemos. Nenhuma guerra ou conflito os alcançará aqui.",
  ui_story_31530601_167_dialog_content = "Como Grande Marechal da Federação Illumina... Eu juro vigiar tudo.",
  ui_story_31530601_168_dialog_content = "Estarei sempre aqui.",
  ui_story_31530601_169_dialog_content = "(A Iluminação Iluminada... Eu vejo agora.)",
  ui_story_31530601_170_dialog_content = "(É impossível ver essa pessoa como apenas uma boa amiga. Ela é muito mais do que isso.)",
  ui_story_31530601_171_dialog_content = "Agora então, meu amigo <color=#FFB400>livre e indisciplinado</color>... Já que você tem uma opinião tão alta deste lugar, talvez pudéssemos trocar um terreno em Eraveil por um bairro aqui? O que você acha?",
  ui_story_31530601_172_dialog_content = "Posso ajudá-lo a se alistar em nosso exército e até começar como tenente!",
  ui_story_31530601_173_dialog_content = "... Você quer que eu lhe dê minha casa em troca de trabalhar para você? O que aconteceu com o não fazer piada com seus amigos?!",
  ui_story_31530601_174_dialog_content = "Hahahaha!"
}
return config
